bool unicode_is_banned_codepoint(u32 cp)
{
	size_t lo = 0, hi = ARRAY_SIZE(banned_ranges);

	while (lo < hi) {
		size_t mid = lo + (hi - lo) / 2;
		const struct unicode_range *r = &banned_ranges[mid];

		if (cp < r->start)
			hi = mid;
		else if (cp > r->end)
			lo = mid + 1;
		else
			return true;
	}
	return false;
}
